from admissions_records import *
def src(url,en,ru):return S(url,L(en,ru),access='web-html-read')
unknown={'satPolicy':'unknown','note':L('The applicable academic entrance qualification must be checked separately. Absence of SAT on a language page does not establish test-optional admission.','Применимая академическая вступительная квалификация проверяется отдельно. Отсутствие SAT на языковой странице не означает test-optional.')}

record('frankfurt-school',[route(id='bba-english',label=L('Bachelor in Business Administration — English starting route','Bachelor in Business Administration — начало на английском'),programmeIds=['business'],applicability={**cycle('September 2027',[2027]),'intakes':['fall-2027']},english={'requirement':'internal-assessment','ielts':{'accepted':None,'min':None},'note':L('An English certificate is not required with the BBA application: the online Assessment Centre includes English testing. Not meeting that assessment leads to discussion of further options, not an assumed IELTS exemption.','Сертификат английского не требуется с заявкой BBA: английский проверяется в онлайн Assessment Centre. При недостаточном результате обсуждаются дальнейшие варианты, а не предполагается освобождение по IELTS.')},academic={'satPolicy':'unknown','note':L('A recognised school-leaving qualification and successful Assessment Centre are required. The centre tests quantitative, verbal and figural reasoning plus interview. A universal SAT/ACT substitute rule is not established.','Нужны признанная школьная квалификация и успешный Assessment Centre. Центр проверяет количественное, вербальное и образное мышление, затем интервью. Универсальное правило замены через SAT/ACT не установлено.')},note=L('Start in English or German; from semester 4 all courses are English. Corporate-partner CompactTrack requires German C1; it is not the same as the general English starting route.','Можно начать на английском или немецком; с 4-го семестра все предметы на английском. CompactTrack с корпоративным партнёром требует немецкий C1; это не тот же маршрут, что общее начало на английском.'),sources=[src('https://www.frankfurt-school.de/en/home/study/bachelor/bachelor-in-business-administration','Frankfurt School BBA September 2027 requirements','Frankfurt School BBA: требования сентября 2027')])], 'Replaced an assumed IELTS threshold with the published internal English assessment and German-C1 partner-route limitation.', ['IELTS acceptance as an assessment substitute and exact foreign-school equivalence not established.'])

enurl='https://www.leuphana.de/en/college/application/international-applications/requirements/language-proficiency/eng-maj2.html'
deurl='https://www.leuphana.de/en/college/application/international-applications/requirements/language-proficiency/ger-maj2.html'
ens=src(enurl,'Leuphana English-major language requirements','Leuphana: языковые требования английских специальностей')
des=src(deurl,'Leuphana German-major language requirements','Leuphana: языковые требования немецких специальностей')
record('leuphana-university-luneburg',[route(id='english-majors',label=L('English-language College majors: Economics, IBA and listed programmes','Англоязычные специальности College: Economics, IBA и перечисленные программы'),programmeIds=['economics','business','social-sciences','arts','psychology'],english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'variant':'IELTS Academic','min':6.5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'pre2026','min':90,'sections':{'reading':21,'listening':19,'speaking':22,'writing':20}},{'period':'post2026','min':4.5,'sections':dict.fromkeys(['reading','writing','listening','speaking'],4)}]},'alternatives':L('PTE Academic 63; Cambridge B2 First 175/C1 Advanced 180/C2 Proficiency 200; TOEIC four skills with published thresholds.','PTE Academic 63; Cambridge B2 First 175/C1 Advanced 180/C2 Proficiency 200; TOEIC по четырём навыкам с опубликованными порогами.'),'waiver':L('Specified European Baccalaureate English 8, IB English A HL 6, a completed English-language degree, or an English-school entrance qualification. Qualification, not nationality, determines proof. German is not required for an English-language major.','Указанный европейский Baccalaureate English 8, IB English A HL 6, завершённая англоязычная степень либо англоязычная школьная вступительная квалификация. Подтверждение зависит от квалификации, а не гражданства. Для англоязычной специальности немецкий не требуется.')},academic=unknown,sources=[ens]),
 route(id='german-majors',label=L('German-language College majors — engineering has separate rules','Немецкоязычные специальности College — у инженерии отдельные правила'),language='de',english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'variant':'IELTS Academic','min':4.5,'role':'admission'},'alternatives':L('German majors also require English proof: TOEFL legacy 60 with stated sections, new 3.5 with stated sections; PTE Academic 50, specified Cambridge or TOEIC tests, or qualifying English-medium education.','Немецкоязычные специальности также требуют английский: TOEFL прежний 60 с указанными секциями, новый 3,5 с указанными секциями; PTE Academic 50, указанные Cambridge/TOEIC либо подходящее англоязычное образование.')},academic=unknown,localLanguage=[{'name':'German','requirement':L('Unrestricted route: DSH-2, TestDaF 4 in every part (16 total), telc Deutsch C1 Hochschule, Goethe C2 or listed equivalents. Goethe C1/DSH-1 can lead to conditional admission with compulsory preparation and DSH-2 by semester 2; not unrestricted entry.','Безусловный маршрут: DSH-2, TestDaF 4 в каждой части (16 всего), telc Deutsch C1 Hochschule, Goethe C2 либо перечисленные эквиваленты. Goethe C1/DSH-1 могут дать условный приём с обязательной подготовкой и DSH-2 к концу 2-го семестра; это не безусловное поступление.')}],sources=[des])], 'Separated English-major IELTS 6.5 from the German-major English 4.5 plus German examination; preserved conditional DSH restrictions.', ['Fall 2027-labelled rules, school equivalence and engineering/teacher-training exceptions need separate verification.'])

hsrw='https://www.hochschule-rhein-waal.de/fileadmin/upload_redaktion/Dezernate/Studierendenangelegenheiten/ZSB/_Dokumente/Accepted_English_Language_Proofs-40.pdf'
record('rhine-waal-university',[route(id='english-b2',label=L('English-taught bachelor programmes requiring B2 — campus depends on programme','Англоязычные программы бакалавриата с B2 — кампус зависит от программы'),english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'variant':'IELTS Academic','min':5.5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':72}]},'alternatives':L('Published B2 certificates include PTE 59–75, named Cambridge awards, telc B2, UNIcert II, specified IGCSE and three TOEIC skill tests. C1 is a different category: IELTS 7.0 / TOEFL 95.','Опубликованные сертификаты B2 включают PTE 59–75, указанные Cambridge, telc B2, UNIcert II, определённые IGCSE и три теста навыков TOEIC. C1 — другая категория: IELTS 7,0 / TOEFL 95.'),'waiver':L('German entrance qualification can demonstrate B2. The certificate list also recognises specified English-country school diplomas/degrees and IB English 5; an unspecified medium-of-instruction letter is not assumed sufficient.','Немецкая вступительная квалификация может подтвердить B2. Список также признаёт определённые школьные дипломы/степени англоязычных стран и IB English 5; произвольное письмо о языке обучения не считается достаточным.')},academic=unknown,note=L('The official overview links this B2 certificate list for bachelor applicants. This is not a C1/master threshold and does not confirm every programme or Fall 2027 policy.','Официальный обзор ссылается на этот список B2 для бакалавров. Это не порог C1/магистратуры и не подтверждение каждой программы или правил Fall 2027.'),sources=[src('https://www.hochschule-rhein-waal.de/en/study/before-starting-university/overview-for-prospective-students','Rhine-Waal bachelor B2 requirement','Rhine-Waal: B2 для бакалавриата'),S(hsrw,L('Rhine-Waal accepted English proofs: B2 and C1 columns','Rhine-Waal: принимаемые подтверждения английского, колонки B2 и C1'),pages=[1],access='pdf-read',quote='minimum score 5.5')])], 'Recorded the actual linked B2 IELTS 5.5 table rather than imposing an old 6.0 or C1 threshold.', ['New TOEFL 1–6 cutoff, IELTS sections, exact programme/campus and Fall 2027-specific applicability remain unconfirmed.'])

tum='https://www.tum.de/en/studies/application/application-info-portal/admission-requirements/language-certificates'
record('technical-university-of-munich',[route(id='german-language-programmes',label=L('German-language degree route — programme regulations govern','Немецкоязычный маршрут — действуют правила программы'),language='de',english={'note':L('An IELTS score does not replace German proof. English requirements vary; the general IELTS 6.5 certificate list is not a universal requirement for every TUM bachelor.','IELTS не заменяет немецкий. Требования английского различаются; общий список сертификатов с IELTS 6,5 не является универсальным правилом каждого бакалавриата TUM.')},academic=unknown,localLanguage=[{'name':'German','requirement':L('DSH-2, TestDaF level 4 in all parts, DSD II at least B2 in all parts, telc Deutsch C1 Hochschule, Goethe C2 or listed equivalents. German entrance qualification and specified educational proofs can qualify. Aerospace/Information Engineering have separate lower-level German alternatives.','DSH-2, TestDaF 4 во всех частях, DSD II минимум B2 во всех частях, telc Deutsch C1 Hochschule, Goethe C2 либо перечисленные эквиваленты. Подходят немецкая вступительная квалификация и определённые образовательные подтверждения. У Aerospace/Information Engineering отдельные варианты немецкого более низкого уровня.')}],note=L('For six named bachelor programmes, English is checked through aptitude assessment and an English certificate is not required with the application. Confirm the exact degree, campus and its German/English combination.','Для шести названных программ бакалавриата английский проверяется при оценке способностей, и сертификат английского не нужен с заявкой. Уточните конкретную программу, кампус и сочетание немецкого/английского.'),sources=[src(tum,'TUM language certificates and bachelor exceptions','TUM: языковые сертификаты и исключения бакалавриата')])], 'Made German tests and programme-specific English assessment exceptions explicit without imposing a graduate-style IELTS cutoff on every bachelor.', ['Exact bachelor/campus, SAT or other qualification criteria and a Fall 2027-labelled programme regulation require individual confirmation.'])
finish()
